from pathlib import Path
import json
p=Path('docs/player-mobile');b=json.loads((p/'before-mobile.json').read_text());a=json.loads((p/'after-mobile.json').read_text());assert a['passed']and len(a['samples'])==11
notes={
'mobile-844-room':('Găng xanh đậm, tay áo trắng; toàn phòng có các bàn, tủ hút và bảng.','Găng nitrile/ống tay ivory thống nhất; bố trí các đồ chính giữ nguyên, marker ở pha chuyển động khác. Auto giảm DPR nên viền bàn/trần răng cưa hơn.','Cặp này cùng pose; kiểm số vị trí/bounds bằng ABBA thay vì coi hai ảnh giống từng pixel.'),
'mobile-844-mirror':('Gương hiển thị người với áo mở và giày hộp; tay cầm màu xanh đậm.','Áo đóng nẹp, giày bo và chổi/hốt xuất hiện trong phản chiếu; target compact khiến mặt nhỏ mềm hơn. HUD giữ góc và toolbar.','Gương cập nhật cách frame chính; ưu tiên đọc trang phục tổng thể ở Low/Auto mobile.'),
'mobile-844-mirror-off-axis':('Nhìn dọc tủ PPE, bảng lối thoát, bồn rửa; phần gương nằm mép trái khung.','Các hộp găng, kính/áo trên tủ vẫn đúng vị trí; tay mới có cổ găng. Marker có pha khác; không còn coi marker như mặt chắn tương tác.','Tên off-axis là quay lệch tâm, không khẳng định gương hoàn toàn khuất; frustum vẫn có thể chạm mép gương.'),
'mobile-844-move-look':('Cuối thao tác còn đứng xa giáo viên và thấy nhiều phần bàn.','Cuối thao tác tới gần giáo viên hơn; mặt/ve áo giáo viên chi tiết và màu găng thống nhất. HUD vẫn ở vị trí góc.','Hai ngón đi/nhìn thực, cùng chuỗi input; endpoint khác do FPS và bước thời gian, không so ảnh như cùng camera cuối.'),
'mobile-740-room':('Góc rộng phòng, găng đậm và giày giáo viên dạng hộp; HUD vừa chiều ngang 740.','Găng mới cùng palette vật phẩm, giáo viên dùng model chung; bàn/tủ/bảng vẫn còn đủ trong khung. Cạnh 3D giảm độ nét theo DPR.','Các số UI là HTML nên vẫn rõ hơn đường chéo hình 3D ở auto thấp.'),
'mobile-740-mirror':('Kính, khẩu trang, áo và hai chân thấy trong gương, tay cầm tông xanh đậm.','Đủ bộ trang phục, tay áo/găng mới và dụng cụ cầm được đồng bộ; gương nhỏ có răng cưa do target compact.','Việc giảm phân giải gương là đánh đổi có ghi nhận; preset High đã được test phục hồi target 512×768.'),
'mobile-740-mirror-off-axis':('Tủ PPE bên trái, lối thoát giữa và bồn rửa bên phải; thanh công cụ không tràn.','Hộp găng, áo treo và kính còn đủ; mặt tủ và cạnh trần thô hơn tại DPR 0,7, tay có chi tiết nếp/găng.','Gương ở ngoài tâm; số lần render còn lớn hơn 0 được ghi thực, không gắn nhãn là culling hoàn toàn.'),
'mobile-740-move-look':('Đã tới gần giáo viên; mặt cũ cầu mắt lồi và áo trắng trơn.','Giáo viên có mắt/mày/ve/cúc và cổ tay; tay player cùng palette nitrile. Nút tương tác và toolbar giữ trong khung.','Hai endpoint gần nhau nhưng không bằng nhau; lượng xoay không còn phụ thuộc số sự kiện chạm.'),
'desktop-room':('Góc phòng với tay xanh/ống trắng, bảng và nội thất đủ.','Tay có cổ găng/đường may và màu đồng bộ; bố trí phòng giữ. Marker ảnh khác pha; khung UI không đổi.','Mẫu FPS này giảm nhẹ dù draw call thấp hơn: chưa có bằng chứng cải thiện cho góc phòng desktop.'),
'desktop-mirror':('Phản chiếu avatar cũ, găng xanh và áo trắng.','Phản chiếu ve/nẹp, giày mới và dụng cụ ở hai tay; các kệ PPE giữ vị trí.','DPR auto thay đổi giữa lượt; so tổng kết tối ưu, không coi là phép so cùng độ phân giải.'),
'desktop-mirror-off-axis':('Dọc kệ găng, áo treo, lối thoát và bồn rửa; gương ở mép.','Giữ các kệ và đồ, găng nhạt đúng palette và tay áo có bo; nhãn nhiệm vụ vẫn đọc được.','Góc lệch gương, cả hai DPR xấp xỉ 0,7; FPS cải thiện nhưng vẫn dưới mức chơi mượt ở CPU throttle 4×.')}
text='\n## Ảnh và đo mobile/desktop cuối\n\n[Trước](before-mobile.json) · [Sau](after-mobile.json). Chrome headless, GPU Intel UHD qua ANGLE/D3D11, CPU throttle 4×, preset Auto; đo callback render chính R3F trong 5 giây (đi/nhìn 6 giây), không dùng số pass `gl.info.render.frame` làm FPS. Mỗi trường hợp một mẫu. Cùng viewport/device DPR/pose đầu nhưng **render DPR có chủ ý thay đổi theo auto quality**; cần đọc cùng phép ABBA cố định DPR ở trên. Đây là môi trường máy tính giả lập cảm ứng, chưa là đo trên điện thoại vật lý.\n\nCác bảng `review-mobile-1…4.jpg` và `review-desktop.jpg` đã được soi cùng ảnh gốc.\n\n'
short='\n## Kết quả Auto theo từng góc\n\n[Trước](before-mobile.json) · [Sau](after-mobile.json) · [Audit ảnh và giới hạn](AUDIT.vi.md#ảnh-và-đo-mobiledesktop-cuối). CPU throttle 4×, GPU Intel UHD/D3D11 của máy tính; chưa thử điện thoại vật lý. Render DPR thay đổi theo auto quality, nên không gán toàn bộ mức tăng FPS cho ghép mesh.\n\n| Khung/cảnh | FPS trước → sau | DPR trước → sau |\n|---|---:|---:|\n'
for n in a['samples']:
 id=n['viewport']['id']+'-'+n['scene'];o=next(r for r in b['samples']if r['viewport']['id']==n['viewport']['id']and r['scene']==n['scene']);before,after,limit=notes[id]
 text+=f'### {id}\n\n[Ảnh trước](before-{id}.png) · [Ảnh sau](after-{id}.png)\n\n- Trước, đã soi: {before}\n- Sau, đã soi: {after}\n- Giới hạn: {limit}\n- FPS render chính: {o["timing"]["fps"]:.2f} → {n["timing"]["fps"]:.2f}; P95 frame: {o["timing"]["p95"]:.1f} → {n["timing"]["p95"]:.1f} ms.\n- Render DPR: {o["renderer"]["pixelRatio"]:.2f} → {n["renderer"]["pixelRatio"]:.2f}; snapshot draw call: {o["renderer"]["render"]["calls"]} → {n["renderer"]["render"]["calls"]}; lượt cập nhật gương trong cửa sổ: {o["mirrorUpdates"]} → {n["mirrorUpdates"]}. Snapshot có thể rơi vào frame có/không render gương, không dùng như draw call trung bình.\n\n'
 short+=f'| {id} | {o["timing"]["fps"]:.2f} → {n["timing"]["fps"]:.2f} | {o["renderer"]["pixelRatio"]:.2f} → {n["renderer"]["pixelRatio"]:.2f} |\n'
short+='\nMẫu desktop nhìn phòng giảm 10,03 → 9,31 FPS; không khẳng định mọi góc đều nhanh hơn. Các P95 dưới CPU 4× vẫn cao: đã giảm chi phí và cải thiện input, nhưng chưa chứng nhận 30/60 FPS trên điện thoại thật. Muốn đánh giá tăng tốc riêng geometry, dùng bảng ABBA cố định DPR. Build thành công còn cảnh báo kích thước các chunk lớn.\n\n[Validation](validation.json): 322 kiểm tra browser liên quan đã qua; catalog đủ 134 biến thể/805 kiểm tra, trong đó 13 model × 4 góc được render lại ở lượt này. Core/lint/build và kiểm buffer/touch đều qua.\n'
for name,block,marker in [('AUDIT.vi.md',text,'\n## Ảnh và đo mobile/desktop cuối'),('README.md',short,'\n## Kết quả Auto theo từng góc')]:
 file=p/name;existing=file.read_text(encoding='utf-8');file.write_text(existing.split(marker)[0]+block,encoding='utf-8')
